import type { Comanda } from "@/types/cocinero";
import Badge from "@/components/ui/badge";

interface ComandaCardProps {
  comanda: Comanda;
  onClick: (comanda: Comanda) => void;
}

export default function ComandaCard({comanda, onClick}: ComandaCardProps){

  const bgColores = {
    pendiente: "bg-yellow-50 border-yellow-500 hover:bg-yellow-100",
    en_cocina: "bg-blue-50 border-blue-500 hover:bg-blue-100",
    listo: "bg-green-50 border-green-500 hover:bg-green-100",
    cancelado: "bg-gray-50 border-gray-500 hover:bg-gray-100"
  };

  const badgeVariants: Record<
    string,
    "success" | "info" | "warning" | "info"
  > = {
    pendiente: "warning",
    en_cocina: "info",
    listo: "success",
    cancelado: "info",
  };

  return(
    <button
          onClick={() => onClick(comanda)}
          className={`p-4 rounded-xl border-l-4 shadow-sm transition-all text-left flex flex-col justify-between h-28 ${bgColores[comanda.estado]}`}
        >
          <div className="flex justify-between items-start w-full">
            <span className="font-bold text-lg text-gray-800">{comanda.id_mesa.nombre}</span>
            <Badge variant={badgeVariants[comanda.estado]}>{comanda.estado}</Badge>
          </div>
          <div className="text-sm text-gray-600 mt-2 font-medium">
            👤 {comanda.id_mesa.capacidad} pers. | 📍 {comanda.id_mesa.ubicacion}
          </div>
        </button>
  )



}